import{_ as e,o as t,c as r,al as i}from"./chunks/framework.BawR2jEz.js";const d=JSON.parse('{"title":"Обзор интерфейса","description":"Структура админ-панели exDoc — навигация, рабочая область, боковые панели и основные разделы.","frontmatter":{"title":"Обзор интерфейса","description":"Структура админ-панели exDoc — навигация, рабочая область, боковые панели и основные разделы."},"headers":[],"relativePath":"getting-started/interface.md","filePath":"getting-started/interface.md"}'),o={name:"getting-started/interface.md"};function l(n,a,s,h,c,f){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="обзор-интерфеиса" tabindex="-1">Обзор интерфейса <a class="header-anchor" href="#обзор-интерфеиса" aria-label="Permalink to &quot;Обзор интерфейса&quot;">​</a></h1><h2 id="структура-админ-панели" tabindex="-1">Структура админ-панели <a class="header-anchor" href="#структура-админ-панели" aria-label="Permalink to &quot;Структура админ-панели&quot;">​</a></h2><p>Интерфейс exDoc — полноценное Vue 3 SPA внутри OpenCart. Он состоит из нескольких зон:</p><h2 id="левая-панель-навигации" tabindex="-1">Левая панель навигации <a class="header-anchor" href="#левая-панель-навигации" aria-label="Permalink to &quot;Левая панель навигации&quot;">​</a></h2><p>Разделы в том порядке, в каком они идут в панели:</p><ul><li><strong><a href="./../categories/">Категории</a></strong> — иерархическая структура контента</li><li><strong><a href="./../documents/">Документы</a></strong> — единицы контента внутри категорий</li><li><strong><a href="./../collections/">Коллекции</a></strong> — типовые элементы с полями (слайды, карточки, отзывы)</li><li><strong><a href="./../rubrics/">Рубрики</a></strong> — типы контента с настраиваемыми полями</li><li><strong><a href="./../blocks/">Визуальные блоки</a></strong> — блоки с шаблонами, стилями и полями</li><li><strong><a href="./../templates/">Шаблоны</a></strong> — макеты страниц (header/footer)</li><li><strong><a href="./../settings/">Настройки</a></strong> — конфигурация модуля</li></ul><p>Это полный список — то, что видит пользователь с доступом ко всему. Каждый раздел показывается по <a href="./../settings/roles.html">роли</a>: если группе не выдана видимость раздела в сайдбаре, пункта не будет. То же касается и верхнего меню.</p><h2 id="верхнее-меню" tabindex="-1">Верхнее меню <a class="header-anchor" href="#верхнее-меню" aria-label="Permalink to &quot;Верхнее меню&quot;">​</a></h2><ul><li><strong><a href="./../search/">Поиск</a></strong> — глобальный поиск по всем сущностям (блоки, рубрики, компоненты, шаблоны). Поиск по имени, хэштегу, содержимому шаблонов, стилей и скриптов</li><li><strong><a href="./../log/">Лог</a></strong> — журнал действий с фильтрацией по типу (info, error, warn, debug) и просмотром деталей</li><li><strong><a href="./../file-manager/">Файловый менеджер</a></strong> — загрузка и выбор файлов</li><li><strong><a href="./../fast-settings/">Быстрые настройки</a></strong> — доступ к глобальным стилям, скриптам, SVG-спрайтам и переменным</li><li><strong><a href="./../cache/">Сброс кэша и модификаторов</a></strong> — обновление OCMOD-модификаторов и очистка системного кэша OpenCart</li></ul><h2 id="вкладки-навигации" tabindex="-1">Вкладки навигации <a class="header-anchor" href="#вкладки-навигации" aria-label="Permalink to &quot;Вкладки навигации&quot;">​</a></h2><p>При открытии сущности для редактирования она появляется как вкладка. Можно открыть несколько сущностей одновременно и переключаться между ними. Вкладки поддерживают перетаскивание для изменения порядка.</p><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li><a href="./first-steps.html">Первые шаги</a> — создание первого блока и страницы</li><li><a href="./../blocks/">Блоки</a> — подробнее о блоках</li><li><a href="./../editor/">Редактор</a> — как работать с Twig, SCSS и JavaScript</li></ul>',13)])])}const u=e(o,[["render",l]]);export{d as __pageData,u as default};
